def check_coloring_C4(range_limit=2):
    """
    Tests the 4-coloring based on parity for Condition 1 (Neighboring points must be different colors).
    The coloring C(x, y) is determined by ((x % 2), (y % 2)).
    This assigns 4 colors (00, 01, 10, 11).
    """
    # Map parity tuple to a unique color index (0 to 3)
    def color(x, y):
        return (x % 2) * 2 + (y % 2)

    max_coord = range_limit

    # Iterate over all points (x, y) in the specified range
    for x in range(-max_coord, max_coord + 1):
        for y in range(-max_coord, max_coord + 1):
            c1 = color(x, y)

            # Check all 8 distinct neighbors (a, b)
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue # Skip the point itself

                    a, b = x + dx, y + dy
                    c2 = color(a, b)

                    if c1 == c2:
                        print(f"Contradiction found at ({x}, {y}) and neighbor ({a}, {b}). Both have color {c1}.")
                        return False

    print("Successfully verified 4-coloring for Condition 1 across the test range.")
    return True

# Test the 4-coloring scheme
is_valid = check_coloring_C4(range_limit=2)
print(f"Test Result: {is_valid}")
